            inputs_dict = sidebar_data["inputs_dict"]
            new_val = RootCallbacks.get_inputs(inputs_dict, inputs_keys)
        elif root_modified > (sidebar_modified + 100):
            new_val = RootCallbacks.get_inputs(root_data, inputs_keys)
        else:
            raise PreventUpdate
