    ##########################################################################
    def Process(self, trace):
        f = None
        line_mode = False
        self.__init__()
        logging.debug("Loading trace: %s", trace)
        try:
            file_name, ext = os.path.splitext(trace)
            if ext.lower() == '.gz':
                f = gzip.open(trace, 'rb')
            else:
                f = open(trace, 'r')
            for line in f:
                try:
                    trace_event = json.loads(line.strip("\r\n\t ,"))
                    if not line_mode and 'traceEvents' in trace_event:
